const $=id=>document.getElementById(id);
const launchToken=location.hash.slice(1);
history.replaceState(null,'',location.pathname);sessionStorage.removeItem('sarasSetup');
const setupSession=SarasSetupSession.create(fetch.bind(window),launchToken);
let loaded=false,pending=null,appUrl="",autoStartup=false;
async function call(path,data){return setupSession.call(path,data)}
let activeFeedback=null;
let connectionFeedback=null,refreshing=false,lastConnectionNotice="";
function note(e,kind=e instanceof Error?'error':'success'){const text=e.message||e;$('notice').textContent=text;$('notice').dataset.state=kind;if(activeFeedback){activeFeedback.textContent=text;activeFeedback.dataset.state=kind}}
async function refresh(){if(refreshing)return;refreshing=true;try{const s=await call('/status');if(!loaded){for(const k of ['url','provider','model','folder'])$(k).value=s.defaults[k];$('remote').checked=true;$('powerPermission').checked=s.defaults.system_controls===true;$('desktopInput').checked=s.defaults.desktop_input===true;$('remoteVoice').checked=s.defaults.remote_voice===true;loaded=true;updateRemoteReset()}appUrl=s.defaults.url;if(s.update_status)$('updateStatus').textContent=s.update_status;if($('voiceConnection')){$('voiceConnection').textContent='Saved website: '+appUrl+' | Voice permission: '+(s.defaults.remote_voice?'ON':'OFF')+' | '+(s.voice?.message||'Restart companion once to load voice diagnostics.');$('voiceConnection').dataset.state=s.voice?.state==='ready'?'success':'loading'}if(connectionFeedback){connectionFeedback.textContent=s.status;connectionFeedback.dataset.state=s.busy?'loading':/attention|failed|error/i.test(s.status)?'error':'success';if(!s.busy){note(s.status,connectionFeedback.dataset.state);connectionFeedback=null}}$('status').textContent=s.status;$('status').dataset.state=/attention|failed|error|unavailable/i.test(s.status)?'error':s.busy?'loading':'success';if((s.busy||/attention|failed|error/i.test(s.status))&&s.status!==lastConnectionNotice){lastConnectionNotice=s.status;if(location.pathname==='/activity'||connectionFeedback)note(s.status,s.busy?'loading':'error');}$('qrPanel').hidden=!s.qr_url;if(s.qr_url){$('qrCode').textContent='Compare this code: '+s.qr_code;$('qrLink').href=s.qr_url;if($('qrImage').dataset.url!==s.qr_url){$('qrImage').dataset.url=s.qr_url;$('qrImage').src='/qr.svg?v='+Date.now()}}if(autoStartup&&s.status.startsWith('Laptop connected')){autoStartup=false;await call('/startup',{enabled:true,confirmed:true})}if(!$('save').dataset.running)$('save').disabled=s.busy;$('logs').textContent=s.logs.join('\n');pending=s.pending;$('pending').hidden=!pending;if(pending)$('pendingText').textContent=pending.tool+'\n'+JSON.stringify(pending.args,null,2)}catch(e){note(e)}finally{refreshing=false}}
async function setupTask(id,fn){const button=$(id);if(button.disabled||button.dataset.running)return;const old=button.textContent;let feedback=document.getElementById(id+'Feedback');if(!feedback){feedback=document.createElement('p');feedback.id=id+'Feedback';feedback.className='action-feedback';feedback.setAttribute('role','status');button.insertAdjacentElement('afterend',feedback)}const previousFeedback=activeFeedback;activeFeedback=feedback;button.dataset.running='1';button.disabled=true;button.setAttribute('aria-busy','true');button.classList.add('is-loading');button.textContent=id==='chooseFolder'?'Choose folder in the Windows window…':'Please wait…';note(id==='chooseFolder'?'Folder window opening. Check behind the browser or press Alt+Tab. You can also paste the folder path directly.':'Working… please wait.','loading');try{await fn();if($('notice').textContent==='Working… please wait.')note(({stop:'PC access stopped.',start:'Connection start requested. Check Activity for the final online status.',yes:'Approval sent. Check the execution log for completion.',no:'Action rejected.'})[id]||'Request completed. Check Activity for connection or execution status.','success')}catch(error){note(error,'error')}finally{delete button.dataset.running;button.disabled=false;button.removeAttribute('aria-busy');button.classList.remove('is-loading');button.textContent=old;activeFeedback=previousFeedback}}
function action(id,fn){$(id).onclick=()=>setupTask(id,fn)}
$('setup').onsubmit=async e=>{e.preventDefault();return setupTask('save',async()=>{if(!confirm('Save these permissions? Mobile approval mode lets your phone-approved actions run while away.'))return;try{const data={};for(const k of ['url','password','key','provider','model','folder'])data[k]=$(k).value;data.vercel_bypass=$('vercelBypass').value;data.system_controls=$('powerPermission').checked;data.remote_voice=$('remoteVoice').checked;data.desktop_input=$('desktopInput').checked;data.reset_local_password=$('resetPassword').checked;data.remote_approval=$('remote').checked;data.confirmed=$('consent').checked;await call('/save',data);connectionFeedback=activeFeedback;$('password').value='';$('key').value='';note('Connecting… wait for the final status. This does not yet mean the companion is online.','loading');await refresh()}catch(e){note(e,'error')}})};
action('models',async()=>{const r=await call('/models',{provider:$('provider').value,key:$('key').value});$('modelList').replaceChildren();for(const model of r.models){const el=document.createElement('option');el.value=model;$('modelList').append(el)}note('Models loaded. Select a model under your provider quota; listed models may require payment.')});
action('chooseFolder',async()=>{const r=await call('/folder',{});if(r.folder){$('folder').value=r.folder;note('Folder selected. Tick permission and Save, test & connect.')}else note('Folder selection cancelled. You can paste a path directly.','loading')});action('openApp',async()=>{const tab=window.open('about:blank','_blank');try{const r=await call('/ensure-app',{});const u=new URL(r.url);if(u.protocol!=='https:'&&u.origin!=='http://127.0.0.1:8965')throw Error('Use HTTPS or local SARAS');if(tab){tab.opener=null;tab.location=u.href}else location.href=u.href}catch(e){if(tab)tab.close();throw e}});action('stop',async()=>{await call('/stop',{});await refresh()});action('start',async()=>{await call('/start',{});await refresh()});action('startup',async()=>{if(confirm('Start SARAS when you sign in to Windows?')){await call('/startup',{enabled:true,confirmed:true});note('Windows startup enabled.')}});action('noStartup',async()=>{await call('/startup',{enabled:false,confirmed:true});note('Windows startup disabled.')});for(const [id,approved]of [['yes',true],['no',false]])action(id,async()=>{if(pending)await call('/approve',{id:pending.id,approved});await refresh()});refresh();setInterval(refresh,3000);

$('easySetup').onsubmit=async e=>{e.preventDefault();return setupTask('easyConnect',async()=>{try{autoStartup=$('easyStartup').checked;await call('/connect-code',{code:$('pairCode').value,vercel_bypass:$('vercelBypass').value,url:$('url').value,folder:$('folder').value,remote_voice:$('remoteVoice').checked,desktop_input:$('desktopInput').checked,confirmed:$('easyConsent').checked,system_controls:$('easySystem').checked});connectionFeedback=activeFeedback;$('pairCode').value='';await refresh()}catch(e){autoStartup=false;note(e,'error')}})};
action('cancelPower',async()=>{await call('/cancel-power',{});note('Shutdown / restart countdown cancelled.')});

action('resetOnly',async()=>{if(!confirm('Reset only the local app password? Chats stay saved; signed-in devices and remote access are revoked.'))return;await call('/reset-password',{url:$('url').value,password:$('password').value,confirmed:true});$('password').value='';$('resetPassword').checked=false;note('Local password updated. Log in with the new password. Your chats and provider settings were kept.');await refresh()});

action('quit',async()=>{if(!confirm('Close this SARAS launcher and its local server? Chats and settings remain saved.'))return;await call('/quit',{confirmed:true});note('SARAS closed. Double-click Start SARAS.cmd to reopen.');});

action('qrConnect',async()=>{await call('/connect-qr',{confirmed:$('easyConsent').checked});await refresh()});

action('checkUpdates',async()=>{const result=await call('/updates/check',{});$('updateStatus').textContent=result.message||(result.available?'Signed update available: '+result.version:'No newer update');});
action('stageUpdate',async()=>{if(!confirm('Download and verify the signed beta update? The active release stays in place.'))return;const result=await call('/updates/stage',{confirmed:true});$('updateStatus').textContent=result.message+' '+result.path;});

function updateRemoteReset(){const remote=$('url').value.replace(/\/$/,'')!=='http://127.0.0.1:8965';const mode=$('connectionMode');if(mode){mode.textContent=remote?'Account connection: configure AI in the AI settings panel. The paired phone uses this laptop’s selected provider.':'LOCAL app selected: this will use laptop AI settings. For online use, paste your Preview HTTPS URL above.';mode.dataset.state=remote?'success':'loading'}for(const id of ['provider','key','model']){const field=$(id);field.disabled=remote;const label=field.closest('label');if(label)label.hidden=remote}$('models').hidden=remote;$('resetOnly').disabled=remote;$('resetPassword').disabled=remote;if(remote)$('resetPassword').checked=false}
$('url').addEventListener('input',updateRemoteReset);

action('savePowerPermission',async()=>{await call('/permissions',{confirmed:true,system_controls:$('powerPermission').checked});note('Power permission saved. Existing laptop connection kept.');});

action('saveVoicePermission',async()=>{const r=await call('/permissions',{confirmed:true,remote_voice:$('remoteVoice').checked});note('Voice permission '+(r.voice_enabled?'enabled':'disabled')+' for saved server: '+r.server_url+'. Pairing kept.');});

action('applyUpdate',async()=>{if(!confirm('Install the verified update? Stop PC access first. Saved chats/settings stay; restart SARAS after installation.'))return;const result=await call('/updates/apply',{confirmed:true});$('updateStatus').textContent=result.message;note(result.message);});

const rollbackButton=document.createElement('button');rollbackButton.type='button';rollbackButton.id='rollbackUpdate';rollbackButton.className='v2-outline';rollbackButton.textContent='Restore previous installed version';document.getElementById('applyUpdate').after(rollbackButton);action('rollbackUpdate',async()=>{if(!confirm('Restore the previous installed version? Stop PC access first. Chats and settings are kept.'))return;const result=await call('/updates/rollback',{confirmed:true});document.getElementById('updateStatus').textContent=result.message;note(result.message)});
